mkdir -p /workspace/.build
cat > /workspace/.build/test_lapacke.c <<'C'
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
typedef long long i64;
extern int scipy_LAPACKE_dgeev64_(int layout, char jobvl, char jobvr, i64 n, double* a, i64 lda, double* wr, double* wi, double* vl, i64 ldvl, double* vr, i64 ldvr);
static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+1e-9*ts.tv_nsec;}
int main(){
  int ns[]={2,4,6,8,10};
  for(int t=0;t<5;t++){
    int n=ns[t];
    double A[100],a[100],wr[10],wi[10],vr[100],vl[1];
    for(int i=0;i<n*n;i++) A[i]=(double)rand()/RAND_MAX-0.5;
    int R=20000; double st=now(); volatile double sink=0;
    for(int r=0;r<R;r++){
      memcpy(a,A,sizeof(double)*n*n);
      int info=scipy_LAPACKE_dgeev64_(102,'N','V',n,a,n,wr,wi,vl,1,vr,n);
      sink+=wr[0]+wi[0]+vr[0]+info;
    }
    double dt=(now()-st)/R;
    printf("n=%d lapacke C %.2f us sink=%f\n",n,dt*1e6,(double)sink);
  }
}
C
cd /workspace/.build
LIB=$(ls /usr/local/lib/python3.13/site-packages/numpy.libs/libscipy_openblas64_*.so)
/workspace/.build/ziglang/zig cc -O3 -o test_lapacke test_lapacke.c "$LIB" -Wl,-rpath,/usr/local/lib/python3.13/site-packages/numpy.libs -lm -Wl,--allow-shlib-undefined 2>&1 | head -30
./test_lapacke

cat > /workspace/.build/test_dgeev.c <<'C'
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <stddef.h>
typedef long long i64;
extern void scipy_dgeev_64_(char*,char*,i64*,double*,i64*,double*,double*,double*,i64*,double*,i64*,double*,i64*,i64*, size_t, size_t);
static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+1e-9*ts.tv_nsec;}
int main(){
  int ns[]={2,4,6,8,10};
  for(int t=0;t<5;t++){
    int n=ns[t];
    double A[100],a[100],wr[10],wi[10],vr[100],vl[1],work[1000];
    for(int i=0;i<n*n;i++) A[i]=(double)rand()/RAND_MAX-0.5;
    i64 nn=n,lda=n,ldvl=1,ldvr=n,lwork=1000,info=0;
    int R=20000; double st=now(); volatile double sink=0;
    for(int r=0;r<R;r++){
      memcpy(a,A,sizeof(double)*n*n);
      scipy_dgeev_64_("N","V",&nn,a,&lda,wr,wi,vl,&ldvl,vr,&ldvr,work,&lwork,&info,1,1);
      sink+=wr[0]+wi[0]+vr[0]+info;
    }
    double dt=(now()-st)/R;
    printf("n=%d dgeev C %.2f us sink=%f info=%lld\n",n,dt*1e6,(double)sink,(long long)info);
  }
}
C
